function trimTriples(s: string): string {
  let i = 2;
  while (i < s.length) {
    if (s[i] === s[i - 1] && s[i] === s[i - 2]) s = s.slice(0, i) + s.slice(i + 1);
    else i++;
  }
  return s;
}

